SELECT id, codef_connection_id, organization_code, organization_name, business_type, connection_status
FROM codef_connected_institutions
WHERE codef_connection_id = #{codefConnectionId}
  AND organization_code = #{organizationCode}
  AND business_type = #{businessType}
  AND is_active = TRUE
LIMIT 1

SELECT id, account_number, balance
FROM accounts
WHERE user_id = #{userId}
  AND organization_code = #{organizationCode}
  AND account_number = #{accountNumber}
LIMIT 1

SELECT id, account_number, balance
FROM accounts
WHERE user_id = #{userId}
  AND account_number = #{accountNumber}
  AND is_deleted = 0
LIMIT 1

mapper.update:
UPDATE cards
SET linked_account_id = #{accountId}, updated_at = NOW()
WHERE user_id = #{userId}
  AND payment_account_number = #{accountNumber}
  AND is_deleted = 0

mapper.select:
SELECT a.id, a.account_name, a.account_number, a.account_type, a.balance,
       a.organization_code
FROM accounts a
WHERE a.id = #{accountId}
AND a.user_id = #{userId}
AND a.is_deleted = 0

SELECT t.id, t.account_id, t.card_id, c.card_type AS source_card_type, t.transaction_date, t.transaction_time, t.transaction_type, t.transaction_region, t.amount, t.balance_after, t.merchant_name, t.merchant_type, t.memo, t.category_id, t.original_amount, t.applied_exchange_rate, t.currency_id, sc.category_name, COALESCE(c.card_name, a.account_name) AS payment_method_name, t.category_source, t.category_confidence, t.category_classified_at FROM transactions t LEFT JOIN accounts a ON a.id = t.account_id AND a.is_deleted = 0 LEFT JOIN cards c ON c.id = t.card_id AND c.is_deleted = 0 LEFT JOIN spending_categories sc ON sc.id = t.category_id WHERE (t.account_id = #{accountId} OR c.linked_account_id = #{accountId}) AND t.is_deleted = 0
AND t.transaction_date >= #{startDate}
AND t.transaction_date <= #{endDate}
AND t.transaction_type = #{type}
ORDER BY t.transaction_date DESC, t.transaction_time DESC

mapper.update:
UPDATE accounts
SET is_deleted = 1, updated_at = NOW(), deleted_at = NOW()
WHERE id = #{accountId}
AND user_id = #{userId}
AND is_deleted = 0

mapper.select:
SELECT DATE_FORMAT(t.transaction_date, '%Y-%m-%d') AS date, SUM(CASE WHEN t.transaction_type = 'DEPOSIT' THEN t.amount ELSE 0 END) AS totalDeposit, SUM(CASE WHEN t.transaction_type = 'WITHDRAWAL' THEN t.amount ELSE 0 END) AS totalWithdrawal FROM transactions t JOIN accounts a ON t.account_id = a.id WHERE a.user_id = #{userId} AND YEAR(t.transaction_date) = #{year} AND MONTH(t.transaction_date) = #{month} AND t.is_deleted = 0 AND a.is_deleted = 0
AND t.transaction_type = #{type}
GROUP BY t.transaction_date ORDER BY t.transaction_date

SELECT id, user_id, codef_connection_id, card_name, masked_card_number, card_type, organization_code,
       payment_account_number, linked_account_id, is_deleted, last_synced_at
FROM cards
WHERE user_id = #{userId}
  AND masked_card_number = #{maskedCardNumber}
LIMIT 1

SELECT id, user_id, codef_connection_id, card_name, masked_card_number, card_type, organization_code,
       payment_account_number, linked_account_id, last_synced_at
FROM cards
WHERE id = #{cardId}
  AND user_id = #{userId}
  AND is_deleted = 0

mapper.update:
UPDATE cards
SET is_deleted = 1, deleted_at = NOW(), updated_at = NOW()
WHERE id = #{cardId}
  AND user_id = #{userId}
  AND is_deleted = 0

UPDATE user_travel_cards
SET is_deleted = TRUE, deleted_at = NOW(), updated_at = NOW()
WHERE user_id = #{userId}
  AND masked_card_number = #{maskedCardNumber}
  AND is_deleted = FALSE
